// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: that responsibility still
// lives in the render loop `frame()` (debt #2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Record the pre-move position: brick collision in frame() sweeps the
  // segment (px,py) → (x,y) to catch crossings a discrete test would miss.
  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle: swept test against the top surface. A discrete band test would
  // let a fast ball jump the band in one step (26.5px > PADDLE_H + 2·BALL_R
  // at level 4, dt capped at 50ms); the plane crossing cannot be skipped.
  if (ball.vy > 0) {
    const prevBottom = ball.py + ball.r;
    const bottom = ball.y + ball.r;
    const xMin = paddle.x - ball.r;
    const xMax = paddle.x + paddle.w + ball.r;
    if (prevBottom <= paddle.y && bottom > paddle.y) {
      // Crossed the paddle's top plane this step: interpolate the hit point.
      const t = (paddle.y - prevBottom) / (bottom - prevBottom);
      const xAtHit = ball.px + (ball.x - ball.px) * t;
      if (xAtHit >= xMin && xAtHit <= xMax) {
        reflectOffPaddle(state, xAtHit);
      }
    } else if (prevBottom > paddle.y && ball.y - ball.r < paddle.y + paddle.h && ball.x >= xMin && ball.x <= xMax) {
      // Started inside the paddle region (previous frame skipped the plane):
      // still catch it instead of letting it clip through.
      reflectOffPaddle(state, ball.x);
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// Smallest |hit| a paddle rebound may produce. Without this guard, a contact
// at the exact center (hit = 0) zeroes vx and traps the ball in a vertical
// loop that never reaches the rest of the grid.
const PADDLE_MIN_HIT = 0.15;

// Reflects the ball off the paddle's top surface at horizontal position
// `hitX`. The rebound angle follows the classic breakout mapping (hit ∈
// [-1, 1] → horizontal deflection) but both components are recomputed from
// the level speed, so a rebound always leaves the paddle at ballSpeed(level).
function reflectOffPaddle(state, hitX) {
  const { ball, paddle } = state;
  const speed = ballSpeed(state.level);
  let hit = (hitX - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
  hit = Math.max(-1, Math.min(1, hit));
  if (Math.abs(hit) < PADDLE_MIN_HIT) {
    hit = hit === 0 ? PADDLE_MIN_HIT : Math.sign(hit) * PADDLE_MIN_HIT;
  }
  ball.vx = speed * 0.6 * hit;
  // Recompute vy from the level speed: the rebound conserves the norm
  // (vx² + vy² = speed²) instead of drifting with the hit position.
  ball.vy = -Math.sqrt(speed * speed - ball.vx * ball.vx);
  ball.y = paddle.y - ball.r;
  state.combo = 0; // touching the paddle resets the combo
}

